(function(global){
'use strict';
class Tokenizer{constructor(o={}){this.lowercase=o.lowercase??true;this.removeStopWords=o.removeStopWords??false;this.stopWords=new Set(o.stopWords||['the','a','an','and','or','of','to','in','for','on','with','is','are','by']);}tokenize(text=''){let s=String(text).normalize('NFKD').replace(/[\u0300-\u036f]/g,'');if(this.lowercase)s=s.toLowerCase();let t=s.match(/[a-z0-9]+(?:[-_.\/][a-z0-9]+)*/gi)||[];if(this.removeStopWords)t=t.filter(x=>!this.stopWords.has(x));return t;}sentences(text=''){return String(text).split(/(?<=[.!?])\s+/).map(s=>s.trim()).filter(Boolean);}ngrams(tokens,n=2){const out=[];for(let i=0;i<=tokens.length-n;i++)out.push(tokens.slice(i,i+n).join(' '));return out;}}
const MathX={mean:a=>a.reduce((s,v)=>s+v,0)/Math.max(a.length,1),variance(a){const m=this.mean(a);return a.reduce((s,v)=>s+(v-m)**2,0)/Math.max(a.length,1);},std(a){return Math.sqrt(this.variance(a));},euclidean:(a,b)=>Math.sqrt(a.reduce((s,v,i)=>s+(v-b[i])**2,0)),manhattan:(a,b)=>a.reduce((s,v,i)=>s+Math.abs(v-b[i]),0),cosine(a,b){const d=a.reduce((s,v,i)=>s+v*b[i],0),na=Math.sqrt(a.reduce((s,v)=>s+v*v,0)),nb=Math.sqrt(b.reduce((s,v)=>s+v*v,0));return d/(na*nb||1);},jaccard(a,b){const A=new Set(a),B=new Set(b);return [...A].filter(x=>B.has(x)).length/(new Set([...A,...B]).size||1);}};
class TFIDF{constructor(){this.vocab=[];this.idf=[];}fit(docs){const t=new Tokenizer({removeStopWords:true}),sets=docs.map(d=>new Set(t.tokenize(d))),N=docs.length;this.vocab=[...new Set(sets.flatMap(s=>[...s]))];this.idf=this.vocab.map(term=>Math.log((1+N)/(1+sets.filter(s=>s.has(term)).length))+1);return this;}transform(doc){const t=new Tokenizer({removeStopWords:true}),tokens=t.tokenize(doc),c={};tokens.forEach(x=>c[x]=(c[x]||0)+1);return this.vocab.map((term,i)=>((c[term]||0)/Math.max(tokens.length,1))*this.idf[i]);}fitTransform(d){this.fit(d);return d.map(x=>this.transform(x));}}
class StandardScaler{fit(X){const n=X[0].length;this.means=[];this.stds=[];for(let j=0;j<n;j++){const c=X.map(r=>r[j]);this.means.push(MathX.mean(c));this.stds.push(MathX.std(c)||1);}return this;}transform(X){return X.map(r=>r.map((v,j)=>(v-this.means[j])/this.stds[j]));}fitTransform(X){return this.fit(X).transform(X);}}
class MinMaxScaler{fit(X){const n=X[0].length;this.min=[];this.max=[];for(let j=0;j<n;j++){const c=X.map(r=>r[j]);this.min.push(Math.min(...c));this.max.push(Math.max(...c));}return this;}transform(X){return X.map(r=>r.map((v,j)=>(v-this.min[j])/((this.max[j]-this.min[j])||1)));}}
function gini(y){const c={};y.forEach(v=>c[v]=(c[v]||0)+1);return 1-Object.values(c).reduce((s,n)=>s+(n/y.length)**2,0);}function majority(y){const c={};y.forEach(v=>c[v]=(c[v]||0)+1);return Object.entries(c).sort((a,b)=>b[1]-a[1])[0][0];}
class DecisionTreeClassifier{constructor({maxDepth=8,minSamplesSplit=2}={}){this.maxDepth=maxDepth;this.minSamplesSplit=minSamplesSplit;}fit(X,y){this.root=this._build(X,y,0);return this;}_build(X,y,d){if(d>=this.maxDepth||X.length<this.minSamplesSplit||new Set(y).size===1)return{leaf:true,value:majority(y)};let best=null,base=gini(y);for(let f=0;f<X[0].length;f++){const vals=[...new Set(X.map(r=>r[f]))].sort((a,b)=>a-b);for(let i=0;i<vals.length-1;i++){const t=(vals[i]+vals[i+1])/2,li=[],ri=[];X.forEach((r,k)=>(r[f]<=t?li:ri).push(k));if(!li.length||!ri.length)continue;const sc=(li.length/X.length)*gini(li.map(i=>y[i]))+(ri.length/X.length)*gini(ri.map(i=>y[i])),gain=base-sc;if(!best||gain>best.gain)best={f,t,li,ri,gain};}}if(!best||best.gain<=0)return{leaf:true,value:majority(y)};return{leaf:false,feature:best.f,threshold:best.t,left:this._build(best.li.map(i=>X[i]),best.li.map(i=>y[i]),d+1),right:this._build(best.ri.map(i=>X[i]),best.ri.map(i=>y[i]),d+1)};}_one(r,n=this.root){if(n.leaf)return n.value;return this._one(r,r[n.feature]<=n.threshold?n.left:n.right);}predict(X){return X.map(r=>this._one(r));}}
class KNNClassifier{constructor({k=5}={}){this.k=k;}fit(X,y){this.X=X;this.y=y;return this;}predict(X){return X.map(row=>majority(this.X.map((r,i)=>({d:MathX.euclidean(r,row),y:this.y[i]})).sort((a,b)=>a.d-b.d).slice(0,this.k).map(v=>v.y)));}}
class GaussianNaiveBayes{fit(X,y){this.classes=[...new Set(y)];this.stats={};for(const c of this.classes){const rows=X.filter((_,i)=>y[i]===c);this.stats[c]=rows[0].map((_,j)=>{const col=rows.map(r=>r[j]);return{m:MathX.mean(col),v:MathX.variance(col)+1e-9};});}return this;}_lp(r,c){return this.stats[c].reduce((s,st,j)=>s+(-.5*Math.log(2*Math.PI*st.v)-((r[j]-st.m)**2)/(2*st.v)),Math.log(1/this.classes.length));}predict(X){return X.map(r=>this.classes.map(c=>[c,this._lp(r,c)]).sort((a,b)=>b[1]-a[1])[0][0]);}}
class MultinomialNaiveBayesText{constructor(){this.tokenizer=new Tokenizer({removeStopWords:true});this.docs=[];}train(text,label){this.docs.push({text,label});return this;}fit(){this.labels=[...new Set(this.docs.map(d=>d.label))];this.vocab=new Set();this.counts={};this.totals={};this.docCounts={};for(const l of this.labels){this.counts[l]={};this.totals[l]=0;this.docCounts[l]=0;}for(const d of this.docs){this.docCounts[d.label]++;for(const t of this.tokenizer.tokenize(d.text)){this.vocab.add(t);this.counts[d.label][t]=(this.counts[d.label][t]||0)+1;this.totals[d.label]++;}}return this;}predict(text){if(!this.labels)this.fit();const ts=this.tokenizer.tokenize(text),N=this.docs.length,V=this.vocab.size;return this.labels.map(l=>{let s=Math.log(this.docCounts[l]/N);for(const t of ts)s+=Math.log(((this.counts[l][t]||0)+1)/(this.totals[l]+V));return[l,s];}).sort((a,b)=>b[1]-a[1])[0][0];}}
class KMeans{constructor({clusters=3,maxIterations=100}={}){this.k=clusters;this.maxIterations=maxIterations;}fit(X){if(X.length<this.k)throw new Error('clusters cannot exceed number of rows');this.centroids=X.slice(0,this.k).map(r=>[...r]);let labels=[];for(let it=0;it<this.maxIterations;it++){labels=X.map(r=>this.centroids.map((c,i)=>[i,MathX.euclidean(r,c)]).sort((a,b)=>a[1]-b[1])[0][0]);const next=this.centroids.map((c,k)=>{const rows=X.filter((_,i)=>labels[i]===k);return rows.length?c.map((_,j)=>MathX.mean(rows.map(r=>r[j]))):c;});const m=next.reduce((s,c,i)=>s+MathX.euclidean(c,this.centroids[i]),0);this.centroids=next;if(m<1e-8)break;}this.labels=labels;return this;}predict(X){return X.map(r=>this.centroids.map((c,i)=>[i,MathX.euclidean(r,c)]).sort((a,b)=>a[1]-b[1])[0][0]);}}
class DBSCAN{constructor({epsilon=.5,minPoints=5}={}){this.eps=epsilon;this.minPoints=minPoints;}fit(X){const labels=Array(X.length).fill(undefined);let cl=0;const region=i=>X.map((r,j)=>MathX.euclidean(X[i],r)<=this.eps?j:-1).filter(j=>j>=0);for(let i=0;i<X.length;i++){if(labels[i]!==undefined)continue;let n=region(i);if(n.length<this.minPoints){labels[i]=-1;continue;}labels[i]=cl;const seeds=[...n];for(let s=0;s<seeds.length;s++){const p=seeds[s];if(labels[p]===-1)labels[p]=cl;if(labels[p]!==undefined)continue;labels[p]=cl;const pn=region(p);if(pn.length>=this.minPoints)for(const q of pn)if(!seeds.includes(q))seeds.push(q);}cl++;}this.labels=labels;return this;}}
const Metrics={accuracy:(y,p)=>y.filter((v,i)=>v===p[i]).length/Math.max(y.length,1),confusionMatrix(y,p){const l=[...new Set([...y,...p])],m=Object.fromEntries(l.map(a=>[a,Object.fromEntries(l.map(b=>[b,0]))]));y.forEach((v,i)=>m[v][p[i]]++);return m;},precisionRecallF1(y,p,label){let tp=0,fp=0,fn=0;y.forEach((v,i)=>{if(p[i]===label&&v===label)tp++;else if(p[i]===label)fp++;else if(v===label)fn++;});const precision=tp/(tp+fp||1),recall=tp/(tp+fn||1);return{precision,recall,f1:2*precision*recall/(precision+recall||1)};}};
function trainTestSplit(X,y,testSize=.2,seed=42){let idx=X.map((_,i)=>i),r=seed>>>0,rand=()=>((r=(1664525*r+1013904223)>>>0)/4294967296);for(let i=idx.length-1;i>0;i--){const j=Math.floor(rand()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]];}const n=Math.max(1,Math.round(idx.length*testSize)),te=idx.slice(0,n),tr=idx.slice(n);return{XTrain:tr.map(i=>X[i]),XTest:te.map(i=>X[i]),yTrain:tr.map(i=>y[i]),yTest:te.map(i=>y[i])};}
class RuleEngine{constructor(){this.rules=[];}add(r){this.rules.push(r);return this;}evaluate(input){return this.rules.filter(r=>r.when(input)).map(r=>({id:r.id||null,label:r.label||null,severity:r.severity||'info',reason:typeof r.reason==='function'?r.reason(input):(r.reason||'Rule matched')}));}}
class EnsembleClassifier{constructor(models=[]){this.models=models;}fit(X,y){this.models.forEach(m=>m.fit(X,y));return this;}predict(X){const ps=this.models.map(m=>m.predict(X));return X.map((_,i)=>majority(ps.map(p=>p[i])));}}
class ModelStorage{static save(name,obj){localStorage.setItem('aladinai:'+name,JSON.stringify(obj));}static load(name){const v=localStorage.getItem('aladinai:'+name);return v?JSON.parse(v):null;}static remove(name){localStorage.removeItem('aladinai:'+name);}}
global.AladinAI={version:'0.1.0',Tokenizer,TFIDF,MathX,StandardScaler,MinMaxScaler,DecisionTreeClassifier,KNNClassifier,GaussianNaiveBayes,MultinomialNaiveBayesText,KMeans,DBSCAN,Metrics,trainTestSplit,RuleEngine,EnsembleClassifier,ModelStorage};
})(typeof window!=='undefined'?window:globalThis);
